-- CX-statutory-3: full register-driven clocks and truthful applicability receipts.
-- Expand/contract: old clients retain dates/actions; new facts are nullable. Global reference data only.
SET LOCAL lock_timeout = '2s';
ALTER TABLE statutory_rules ADD COLUMN filing_rule JSONB;
COMMENT ON COLUMN statutory_rules.filing_rule IS 'pd:none — cited filing clock, applicability policy and SETTLED penalty facts';
ALTER TABLE statutory_rules DROP CONSTRAINT statutory_rules_code_check;
ALTER TABLE statutory_rules ADD CONSTRAINT statutory_rules_code_check CHECK (code IN (
