ALTER TABLE insurance_filing_records DROP CONSTRAINT insurance_filing_records_action_check;
ALTER TABLE insurance_filing_records ADD CONSTRAINT insurance_filing_records_action_check CHECK (action IN ('COMPLETE','UNDO','NOT_APPLICABLE','ASSESS'));
ALTER TABLE insurance_filing_records ADD COLUMN not_applicable_reason TEXT,
 ADD COLUMN applicability_facts JSONB, ADD COLUMN total_remuneration_won BIGINT CHECK (total_remuneration_won >= 0),
 ADD COLUMN request_id UUID;
ALTER TABLE insurance_filing_records DROP CONSTRAINT insurance_filing_records_check1;
ALTER TABLE insurance_filing_records ADD CONSTRAINT insurance_filing_evidence_shape CHECK (
 (action='COMPLETE' AND completed_on IS NOT NULL AND not_applicable_reason IS NULL)
 OR (action='UNDO' AND completed_on IS NULL AND receipt_number IS NULL AND loss_code IS NULL AND detail IS NULL AND not_applicable_reason IS NULL AND total_remuneration_won IS NULL AND applicability_facts IS NULL)
 OR (action='NOT_APPLICABLE' AND completed_on IS NULL AND receipt_number IS NULL AND loss_code IS NULL AND total_remuneration_won IS NULL AND not_applicable_reason IN ('AGE_LIMIT','MINOR_OPT_OUT','SHORT_HOURS','DAILY_UNDER_MONTH','DAILY_WORK_CONFIRMATION','TREATY_EXCLUDED','VISA_EXCLUDED','EXECUTIVE_NOT_WORKER','OTHER_LEGAL_GROUND'))
 OR (action='ASSESS' AND completed_on IS NULL AND receipt_number IS NULL AND loss_code IS NULL AND detail IS NULL AND not_applicable_reason IS NULL AND total_remuneration_won IS NULL AND applicability_facts IS NOT NULL));
ALTER TABLE insurance_filing_records DROP CONSTRAINT insurance_filing_records_filing_kind_check;
ALTER TABLE insurance_filing_records ADD CONSTRAINT insurance_filing_records_filing_kind_check CHECK (filing_kind IN ('ACQUIRE','LOSE','LEAVE','RESUME','AGE60','WORK_CONFIRMATION','SEPARATION_CERTIFICATE','ACQUIRE_REQUESTED','MONTHLY_REMUNERATION'));
CREATE TABLE insurance_filing_requests (
 org_id UUID NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT,
 id UUID NOT NULL DEFAULT uuidv7(), employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE RESTRICT,
 source_event_id UUID NOT NULL REFERENCES employee_lifecycle_events(id) ON DELETE RESTRICT,
 filing_kind TEXT NOT NULL CHECK (filing_kind IN ('WORK_CONFIRMATION','SEPARATION_CERTIFICATE','ACQUIRE_REQUESTED','MONTHLY_REMUNERATION')),
 anchor_on DATE NOT NULL, actor UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL,
 PRIMARY KEY(org_id,id), UNIQUE(org_id,actor,idempotency_key), UNIQUE(org_id,source_event_id,filing_kind,anchor_on),
 FOREIGN KEY(actor,org_id) REFERENCES users(id,org_id) ON DELETE RESTRICT);
ALTER TABLE insurance_filing_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE insurance_filing_requests FORCE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON insurance_filing_requests USING (org_id=NULLIF(current_setting('app.current_org',true),'')::uuid)
 WITH CHECK (org_id=NULLIF(current_setting('app.current_org',true),'')::uuid);
REVOKE ALL ON insurance_filing_requests FROM PUBLIC;
GRANT SELECT,INSERT ON insurance_filing_requests TO console_rt;
CREATE TRIGGER trg_filing_request_append_only BEFORE UPDATE OR DELETE ON insurance_filing_requests FOR EACH ROW EXECUTE FUNCTION insurance_filing_records_guard();
ALTER TABLE insurance_filing_records ALTER COLUMN event_id DROP NOT NULL;
ALTER TABLE insurance_filing_records ADD FOREIGN KEY(org_id,request_id) REFERENCES insurance_filing_requests(org_id,id) ON DELETE RESTRICT,
 ADD CONSTRAINT insurance_filing_source_shape CHECK ((event_id IS NULL) <> (request_id IS NULL));
CREATE UNIQUE INDEX insurance_filing_request_version ON insurance_filing_records(org_id,request_id,filing_kind,insurer,version) WHERE request_id IS NOT NULL;
CREATE OR REPLACE FUNCTION insurance_filing_records_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'insurance filing records are append-only' USING ERRCODE='55000'; END IF;
 IF NEW.event_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM employee_lifecycle_events e WHERE e.id=NEW.event_id AND e.org_id=NEW.org_id) THEN
  RAISE EXCEPTION 'insurance filing event must belong to the same organization' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE FUNCTION insurance_filing_request_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM employee_lifecycle_events e WHERE e.id=NEW.source_event_id AND e.org_id=NEW.org_id AND e.employee_id=NEW.employee_id) THEN
  RAISE EXCEPTION 'filing request source and employee must belong to the same organization' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER trg_filing_request_scope BEFORE INSERT ON insurance_filing_requests FOR EACH ROW EXECUTE FUNCTION insurance_filing_request_guard();
INSERT INTO realtime_topic_map(target_type,action,resource_type,carries_id) VALUES ('insurance_filing','insurance_filing.requested','employee',false);
