COMMENT ON COLUMN insurance_filing_records.applicability_facts IS 'pd:personal — assessed insurance facts';
COMMENT ON COLUMN insurance_filing_records.total_remuneration_won IS 'pd:personal — reported total remuneration';
COMMENT ON COLUMN insurance_filing_records.request_id IS 'pd:personal — supplemental filing request';
COMMENT ON COLUMN insurance_filing_requests.org_id IS 'pd:none — filing request org_id';
COMMENT ON COLUMN insurance_filing_requests.id IS 'pd:personal — filing request id';
COMMENT ON COLUMN insurance_filing_requests.employee_id IS 'pd:personal — filing request employee_id';
COMMENT ON COLUMN insurance_filing_requests.source_event_id IS 'pd:personal — filing request source_event_id';
COMMENT ON COLUMN insurance_filing_requests.filing_kind IS 'pd:personal — filing request filing_kind';
COMMENT ON COLUMN insurance_filing_requests.anchor_on IS 'pd:personal — filing request anchor_on';
COMMENT ON COLUMN insurance_filing_requests.actor IS 'pd:personal — filing request actor';
COMMENT ON COLUMN insurance_filing_requests.created_at IS 'pd:none — filing request created_at';
COMMENT ON COLUMN insurance_filing_requests.idempotency_key IS 'pd:none — filing request idempotency_key';
COMMENT ON COLUMN insurance_filing_requests.request_hash IS 'pd:none — filing request request_hash';
